package alpenglow

import (
	"crypto/ed25519"
	"encoding/hex"
	"testing"

	"github.com/stretchr/testify/require"
)

// Vector generated by Agave master fbdcd41e08def72c4e1cb7ffc489b4e0c13fba49
// using solana-bls-signatures 3.3.0 and keypair_from_seed([7; 32]).
func TestBLSSignerMatchesAgave(t *testing.T) {
	identity := ed25519.NewKeyFromSeed(bytesOf(7, ed25519.SeedSize))
	signer, err := DeriveBLSSigner(identity)
	require.NoError(t, err)
	public := signer.PublicKeyCompressed()
	require.Equal(t,
		"a55384b86c60c0e2a13ffdf9087c94495455083acf06ff23d8e7416ee1df1cafccfaad802b527ade7dfe1b02a6bfd79a",
		hex.EncodeToString(public[:]),
	)
	payload, err := EncodeVotePayloadToSign(NewSkipVote(42), 1337)
	require.NoError(t, err)
	require.Equal(t, "032a000000000000003905", hex.EncodeToString(payload))
	signature, err := signer.Sign(payload)
	require.NoError(t, err)
	require.Equal(t,
		"",
		hex.EncodeToString(signature),
	)
}

func bytesOf(value byte, n int) []byte {
	out := make([]byte, n)
	for i := range out {
		out[i] = value
	}
	return out
}
